package com.pethop.adoption;
import com.pethop.adoption.dto.ApplicationDocumentResponse; import com.pethop.common.exception.ApiException; import com.pethop.pet.storage.StoredFile; import com.pethop.security.SecurityUser; import com.pethop.shelter.ShelterRepository; import com.pethop.user.UserRole; import java.io.IOException; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile;
@Service public class ApplicationDocumentService{
 private final ApplicationDocumentRepository documents;private final ApplicationRepository applications;private final ShelterRepository shelters;private final DocumentStorage files;
 public ApplicationDocumentService(ApplicationDocumentRepository d,ApplicationRepository a,ShelterRepository s,DocumentStorage f){documents=d;applications=a;shelters=s;files=f;}
 @Transactional public ApplicationDocumentResponse add(SecurityUser user,UUID applicationId,String type,MultipartFile file)throws IOException{AdoptionApplication app=authorizedApplication(user,applicationId);if(user.user().getRole()!=UserRole.ADOPTER||!app.getAdopter().getId().equals(user.id()))throw ApiException.forbidden("Solo la persona adoptante puede cargar documentos.");if(type==null||!type.matches("[A-Za-z0-9_-]{2,40}"))throw ApiException.badRequest("El tipo de documento no es válido.");if(documents.findAllByApplicationIdOrderByCreatedAtDesc(applicationId).size()>=5)throw ApiException.badRequest("Cada solicitud puede tener hasta 5 documentos.");StoredFile stored=files.store(file);ApplicationDocument d=new ApplicationDocument();d.setApplication(app);d.setUploadedBy(user.user());d.setDocumentType(type);d.setStoragePath(stored.path());d.setOriginalFilename(stored.originalFilename());d.setContentType(stored.contentType());d.setFileSize(stored.size());try{return ApplicationDocumentResponse.from(documents.save(d));}catch(RuntimeException e){try{files.delete(stored.path());}catch(IOException cleanup){e.addSuppressed(cleanup);}throw e;}}
 @Transactional(readOnly=true) public List<ApplicationDocumentResponse> list(SecurityUser user,UUID id){authorizedApplication(user,id);return documents.findAllByApplicationIdOrderByCreatedAtDesc(id).stream().map(ApplicationDocumentResponse::from).toList();}
 @Transactional(readOnly=true) public ApplicationDocument get(SecurityUser user,UUID id){ApplicationDocument d=documents.findById(id).orElseThrow(()->ApiException.notFound("Documento no encontrado."));authorizedApplication(user,d.getApplication().getId());return d;}
 private AdoptionApplication authorizedApplication(SecurityUser user,UUID id){AdoptionApplication app=applications.findById(id).orElseThrow(()->ApiException.notFound("Solicitud no encontrada."));if(user.user().getRole()==UserRole.ADMIN)return app;if(user.user().getRole()==UserRole.ADOPTER&&app.getAdopter().getId().equals(user.id()))return app;if(user.user().getRole()==UserRole.SHELTER&&shelters.findByUserId(user.id()).map(s->s.getId().equals(app.getShelter().getId())).orElse(false))return app;throw ApiException.notFound("Solicitud no encontrada.");}
}
